import{_ as a,f as s,o as t,aq as n}from"./chunks/framework.BvNt3gUw.js";const m=JSON.parse('{"title":"Upgrading To v1.11 From v1.10","description":"","frontmatter":{},"headers":[],"relativePath":"upgrade/v1.11.md","filePath":"en/upgrade/v1.11.md","lastUpdated":1789900690000}'),r={name:"upgrade/v1.11.md"};function o(i,e,l,d,p,c){return t(),s("div",null,e[0]||(e[0]=[n(`<h1 id="upgrading-to-v1-11-from-v1-10" tabindex="-1">Upgrading To v1.11 From v1.10 <a class="header-anchor" href="#upgrading-to-v1-11-from-v1-10" aria-label="Permalink to “Upgrading To v1.11 From v1.10”">​</a></h1><h2 id="v1-11-3" tabindex="-1">v1.11.3 <a class="header-anchor" href="#v1-11-3" aria-label="Permalink to “v1.11.3”">​</a></h2><h3 id="bug-fixes-🐛" tabindex="-1">Bug Fixes 🐛 <a class="header-anchor" href="#bug-fixes-🐛" aria-label="Permalink to “Bug Fixes 🐛”">​</a></h3><ul><li><a href="#the-problem-of-process-interruption-caused-by-panic-in-schedule">The problem of process interruption caused by panic in Schedule</a></li><li><a href="#the-problem-that-dailyat-in-schedule-will-be-executed-every-minute">The problem that DailyAt in Schedule will be executed every minute</a></li></ul><h2 id="v1-11-2" tabindex="-1">v1.11.2 <a class="header-anchor" href="#v1-11-2" aria-label="Permalink to “v1.11.2”">​</a></h2><h3 id="bug-fixes-🐛-1" tabindex="-1">Bug Fixes 🐛 <a class="header-anchor" href="#bug-fixes-🐛-1" aria-label="Permalink to “Bug Fixes 🐛”">​</a></h3><ul><li><a href="#fix-the-data-error-of-using-request-input()-and-request-bind()-at-the-same-time">Fix the data error of using Request.Input() and Request.Bind() at the same time</a></li></ul><h2 id="v1-11-1" tabindex="-1">v1.11.1 <a class="header-anchor" href="#v1-11-1" aria-label="Permalink to “v1.11.1”">​</a></h2><h3 id="exciting-new-features-🎉" tabindex="-1">Exciting New Features 🎉 <a class="header-anchor" href="#exciting-new-features-🎉" aria-label="Permalink to “Exciting New Features 🎉”">​</a></h3><ul><li><a href="#route-add-resource-routing">Route add resource routing</a></li><li><a href="#request-add-new-methods">Request add new methods</a></li><li><a href="#storage-add-new-methods">Storage add new methods</a></li><li><a href="#file-add-new-methods">File add new methods</a></li></ul><h3 id="bug-fixes-🐛-2" tabindex="-1">Bug Fixes 🐛 <a class="header-anchor" href="#bug-fixes-🐛-2" aria-label="Permalink to “Bug Fixes 🐛”">​</a></h3><ul><li><a href="#fix-the-error-of-incorrect-windows-path-for-filesystem">Fix the error of incorrect windows path for Filesystem</a></li><li><a href="#fix-the-panic-of-the-header-method-for-request">Fix the panic of the Header method for Request</a></li></ul><h2 id="v1-11-0" tabindex="-1">v1.11.0 <a class="header-anchor" href="#v1-11-0" aria-label="Permalink to “v1.11.0”">​</a></h2><h2 id="exciting-new-features-🎉-1" tabindex="-1">Exciting New Features 🎉 <a class="header-anchor" href="#exciting-new-features-🎉-1" aria-label="Permalink to “Exciting New Features 🎉”">​</a></h2><ul><li><a href="#orm-add-model-events">Orm add model events(1.11.0)</a></li></ul><h2 id="enhancements-🚀" tabindex="-1">Enhancements 🚀 <a class="header-anchor" href="#enhancements-🚀" aria-label="Permalink to “Enhancements 🚀”">​</a></h2><ul><li><a href="#cache-add-and-optimize-methods">Cache add and optimize methods(1.11.0)</a></li><li><a href="#route-supports-fallback-route">Route supports Fallback route(1.11.0)</a></li><li><a href="#orm-adds-new-methods">Orm adds new methods(1.11.0)</a></li><li><a href="#optimize-facades-config-add">Optimize facades.Config.Add()(1.11.0)</a></li><li><a href="#change-sqlite-driver">Change Sqlite driver(1.11.0)</a></li><li><a href="#contracts-http-add-method-mapping-of-net-http">contracts/http add method mapping of net/http(1.11.0)</a></li></ul><h3 id="breaking-changes-🛠" tabindex="-1">Breaking Changes 🛠 <a class="header-anchor" href="#breaking-changes-🛠" aria-label="Permalink to “Breaking Changes 🛠”">​</a></h3><ul><li><a href="#_2-remove-deprecated-methods">Orm removes methods(1.11.0)</a></li></ul><h3 id="bug-fixes-🐛-3" tabindex="-1">Bug Fixes 🐛 <a class="header-anchor" href="#bug-fixes-🐛-3" aria-label="Permalink to “Bug Fixes 🐛”">​</a></h3><ul><li>The problem that the hashing configuration does not take effect under some situations(1.11.0)</li><li>Non-thread safety problems in RateLimiter(1.11.0)</li></ul><h2 id="upgrade-guide" tabindex="-1">Upgrade Guide <a class="header-anchor" href="#upgrade-guide" aria-label="Permalink to “Upgrade Guide”">​</a></h2><p>Please upgrade the framework step by step according to the content in this section.</p><p><strong>Estimated Upgrade Time: 1 Minutes</strong></p><h3 id="_1-updating-dependencies" tabindex="-1">1. Updating Dependencies <a class="header-anchor" href="#_1-updating-dependencies" aria-label="Permalink to “1. Updating Dependencies”">​</a></h3><p>Update dependencies in the <code>go.mod</code> file:</p><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span>go get -u github.com/goravel/framework@v1.11.0 &amp;&amp; go mod tidy</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="_2-remove-deprecated-methods" tabindex="-1">2. Remove deprecated methods <a class="header-anchor" href="#_2-remove-deprecated-methods" aria-label="Permalink to “2. Remove deprecated methods”">​</a></h3><div class="language- line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span>import (</span></span>
<span class="line"><span>  &quot;github.com/goravel/framework/database&quot;</span></span>
<span class="line"><span>  &quot;github.com/goravel/framework/database/gorm&quot;</span></span>
<span class="line"><span>)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Deprecated</span></span>
<span class="line"><span>database.NewGormInstance()</span></span>
<span class="line"><span>// Replace with(Note: This method is not recommended, please try not to use it)</span></span>
<span class="line"><span>gorm.New()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// Deprecated</span></span>
<span class="line"><span>facades.Orm.Query().Updates()</span></span>
<span class="line"><span>// Replace with(Only modify the method name is fine, no need to modify the parameters)</span></span>
<span class="line"><span>facades.Orm.Query().Update()</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// The Update method changes return value</span></span>
<span class="line"><span>// Before</span></span>
<span class="line"><span>err := facades.Orm.Query().Update()</span></span>
<span class="line"><span>// After</span></span>
<span class="line"><span>res, err := facades.Orm.Query().Update()</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br></div></div><h2 id="new-content" tabindex="-1">New Content <a class="header-anchor" href="#new-content" aria-label="Permalink to “New Content”">​</a></h2><p>This section does not involve code changes, only enhancements.</p><h3 id="orm-add-model-events" tabindex="-1">Orm add model events <a class="header-anchor" href="#orm-add-model-events" aria-label="Permalink to “Orm add model events”">​</a></h3><p>Version: v1.11.1</p><p>Orm models dispatch several events, allowing you to hook into the following moments in a model&#39;s lifecycle: <code>Retrieved</code>, <code>Creating</code>, <code>Created</code>, <code>Updating</code>, <code>Updated</code>, <code>Saving</code>, <code>Saved</code>, <code>Deleting</code>, <code>Deleted</code>, <code>ForceDeleting</code>, <code>ForceDeleted</code>.</p><p><a href="./../orm/getting-started.html#events">For Detail</a></p><h3 id="cache-add-and-optimize-methods" tabindex="-1">Cache add and optimize methods <a class="header-anchor" href="#cache-add-and-optimize-methods" aria-label="Permalink to “Cache add and optimize methods”">​</a></h3><p>Version: v1.11.1</p><h4 id="new-methods" tabindex="-1">New Methods <a class="header-anchor" href="#new-methods" aria-label="Permalink to “New Methods”">​</a></h4><table tabindex="0"><thead><tr><th>Methods</th><th>Action</th></tr></thead><tbody><tr><td>Decrement</td><td><a href="./../digging-deeper/cache.html#incrementing--decrementing-values">Decrement</a></td></tr><tr><td>Increment</td><td><a href="./../digging-deeper/cache.html#incrementing--decrementing-values">Increment</a></td></tr><tr><td>Lock</td><td><a href="./../digging-deeper/cache.html#atomic-locks">Atomic Locks</a></td></tr><tr><td>Store</td><td><a href="./../digging-deeper/cache.html#accessing-multiple-cache-stores">Accessing Multiple Cache Stores</a></td></tr></tbody></table><h4 id="optimize-methods" tabindex="-1">Optimize methods <a class="header-anchor" href="#optimize-methods" aria-label="Permalink to “Optimize methods”">​</a></h4><p><code>Get</code>, <code>GetBool</code>, <code>GetInt</code>, <code>GetInt64</code>, <code>GetString</code>, <code>Pull</code> no longer need to pass a default value(Backwards compatible).</p><h3 id="route-supports-fallback-route" tabindex="-1">Route supports Fallback route <a class="header-anchor" href="#route-supports-fallback-route" aria-label="Permalink to “Route supports Fallback route”">​</a></h3><p>Version: v1.11.1</p><p>You may define a route that will be executed when no other route matches the incoming request.</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#101820;">Route</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Fallback</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">(</span><span style="color:#101820;">ctx http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Context</span><span style="color:#68747D;">)</span><span style="color:#101820;"> http</span><span style="color:#68747D;">.</span><span style="color:#101820;">Response </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">  return ctx</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Response</span><span style="color:#68747D;">().</span><span style="color:#0077B3;">String</span><span style="color:#68747D;">(404,</span><span style="color:#68747D;"> &quot;not found&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">})</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><h3 id="orm-adds-new-methods" tabindex="-1">Orm adds new methods <a class="header-anchor" href="#orm-adds-new-methods" aria-label="Permalink to “Orm adds new methods”">​</a></h3><p>Version: v1.11.1</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>db.Raw</td><td><a href="./../orm/getting-started.html#raw-expressions">Raw Expressions</a></td></tr><tr><td>LockForUpdate</td><td><a href="./../orm/getting-started.html#pessimistic-locking">Pessimistic Locking</a></td></tr><tr><td>SharedLock</td><td><a href="./../orm/getting-started.html#pessimistic-locking">Pessimistic Locking</a></td></tr></tbody></table><h3 id="optimize-facades-config-add" tabindex="-1">Optimize facades.Config.Add() <a class="header-anchor" href="#optimize-facades-config-add" aria-label="Permalink to “Optimize facades.Config.Add()”">​</a></h3><p>Version: v1.11.0</p><p>The <code>configuration</code> parameter of <code>facades.Config.Add()</code> changes to <code>any</code> from <code>map[string]any</code>, make configuration more flexible.</p><p><a href="./../getting-started/configuration.html#set-configuration">For Detail</a></p><h3 id="change-sqlite-driver" tabindex="-1">Change Sqlite driver <a class="header-anchor" href="#change-sqlite-driver" aria-label="Permalink to “Change Sqlite driver”">​</a></h3><p>Because <code>github.com/mattn/go-sqlite3</code> requires <code>CGO</code> to be started, so replacing a third-party package that does not require <code>CGO</code>: <code>github.com/glebarez/go-sqlite</code>.</p><h3 id="contracts-http-add-method-mapping-of-net-http" tabindex="-1">contracts/http add method mapping of net/http <a class="header-anchor" href="#contracts-http-add-method-mapping-of-net-http" aria-label="Permalink to “contracts/http add method mapping of net/http”">​</a></h3><p>Version: v1.11.0</p><p>You can use <code>http.MethodGet</code> in controller directly, instead of import <code>net/http</code>.</p><p><a href="https://github.com/goravel/framework/blob/v1.11.0/contracts/http/method.go" target="_blank" rel="noreferrer">For Detail</a></p><h3 id="route-add-resource-routing" tabindex="-1">Route Add Resource Routing <a class="header-anchor" href="#route-add-resource-routing" aria-label="Permalink to “Route Add Resource Routing”">​</a></h3><p>Version: v1.11.1</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">facades</span><span style="color:#68747D;">.</span><span style="color:#101820;">Route</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Resource</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;/resource&quot;</span><span style="color:#68747D;">,</span><span style="color:#101820;"> resourceController</span><span style="color:#68747D;">)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><a href="./../the-basics/routing.html#resource-routing">For Detail</a></p><h3 id="request-add-new-methods" tabindex="-1">Request Add New Methods <a class="header-anchor" href="#request-add-new-methods" aria-label="Permalink to “Request Add New Methods”">​</a></h3><p>Version: v1.11.1</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>All</td><td><a href="./../the-basics/request.html#retrieving-all-input-data">Retrieving all input data</a></td></tr><tr><td>Host</td><td><a href="./../the-basics/request.html#retrieving-the-request-host">Retrieving the request HOST</a></td></tr><tr><td>Queries</td><td><a href="./../the-basics/request.html#retrieving-input-from-the-query-string">Retrieving input from the query string</a></td></tr></tbody></table><p>About to be deprecated the <code>Form</code>, <code>Json</code> methods, please use <code>Input</code> instead.</p><h3 id="storage-add-new-methods" tabindex="-1">Storage Add New Methods <a class="header-anchor" href="#storage-add-new-methods" aria-label="Permalink to “Storage Add New Methods”">​</a></h3><p>Version: v1.11.1</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>LastModified</td><td><a href="./../digging-deeper/filesystem.html#file-metadata">Get the last modified time of file</a></td></tr><tr><td>MimeType</td><td><a href="./../digging-deeper/filesystem.html#file-metadata">Get the mime type of file</a></td></tr></tbody></table><h3 id="file-add-new-methods" tabindex="-1">File Add New Methods <a class="header-anchor" href="#file-add-new-methods" aria-label="Permalink to “File Add New Methods”">​</a></h3><p>Version: v1.11.1</p><table tabindex="0"><thead><tr><th>Method</th><th>Action</th></tr></thead><tbody><tr><td>LastModified</td><td><a href="./../digging-deeper/filesystem.html#file-metadata">Get the last modified time of file</a></td></tr><tr><td>MimeType</td><td><a href="./../digging-deeper/filesystem.html#file-metadata">Get the mime type of file</a></td></tr><tr><td>Size</td><td><a href="./../digging-deeper/filesystem.html#file-metadata">Get the size of file</a></td></tr></tbody></table><h3 id="fix-the-error-of-incorrect-windows-path-for-filesystem" tabindex="-1">Fix The Error Of Incorrect Windows Path For Filesystem <a class="header-anchor" href="#fix-the-error-of-incorrect-windows-path-for-filesystem" aria-label="Permalink to “Fix The Error Of Incorrect Windows Path For Filesystem”">​</a></h3><p>Version: v1.11.1</p><p>There is a wrong slash in windows system.</p><h3 id="fix-the-panic-of-the-header-method-for-request" tabindex="-1">Fix The Panic Of The Header Method For Request <a class="header-anchor" href="#fix-the-panic-of-the-header-method-for-request" aria-label="Permalink to “Fix The Panic Of The Header Method For Request”">​</a></h3><p>Version: v1.11.1</p><p><code>ctx.Request().Header( key: &quot;token&quot;)</code> will panic.</p><h3 id="fix-the-data-error-of-using-request-input-and-request-bind-at-the-same-time" tabindex="-1">Fix The Data Error Of Using Request.Input() And Request.Bind() At The Same Time <a class="header-anchor" href="#fix-the-data-error-of-using-request-input-and-request-bind-at-the-same-time" aria-label="Permalink to “Fix The Data Error Of Using Request.Input() And Request.Bind() At The Same Time”">​</a></h3><p>Version: v1.11.2</p><p><code>Request.Input()</code> will clear <code>Request.Body</code>, if you use <code>Request.Bind()</code> after that, you will not be able to get the data correctly.</p><h3 id="the-problem-of-process-interruption-caused-by-panic-in-schedule" tabindex="-1">The problem of process interruption caused by panic in Schedule <a class="header-anchor" href="#the-problem-of-process-interruption-caused-by-panic-in-schedule" aria-label="Permalink to “The problem of process interruption caused by panic in Schedule”">​</a></h3><p>Version: v1.11.3</p><p>The Schedule process will interruption when occurring panic, all tasks wil lbe affected.</p><h3 id="the-problem-that-dailyat-in-schedule-will-be-executed-every-minute" tabindex="-1">The problem that DailyAt in Schedule will be executed every minute <a class="header-anchor" href="#the-problem-that-dailyat-in-schedule-will-be-executed-every-minute" aria-label="Permalink to “The problem that DailyAt in Schedule will be executed every minute”">​</a></h3><p>Version: v1.11.3</p><p>Fix the problem that <code>DailyAt</code> will be executed every minute:</p><div class="language-go line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">go</span><pre class="shiki goravel vp-code" style="background-color:#00000000;color:#101820;" tabindex="0"><code><span class="line"><span style="color:#101820;">func </span><span style="color:#68747D;">(</span><span style="color:#101820;">kernel </span><span style="color:#68747D;">*</span><span style="color:#101820;">Kernel</span><span style="color:#68747D;">)</span><span style="color:#0077B3;"> Schedule</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> []</span><span style="color:#101820;">schedule</span><span style="color:#68747D;">.</span><span style="color:#101820;">Event </span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">  return </span><span style="color:#68747D;">[]</span><span style="color:#101820;">schedule</span><span style="color:#68747D;">.</span><span style="color:#101820;">Event</span><span style="color:#68747D;">{</span></span>
<span class="line"><span style="color:#101820;">    facades</span><span style="color:#68747D;">.</span><span style="color:#101820;">Schedule</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Call</span><span style="color:#68747D;">(</span><span style="color:#101820;">func</span><span style="color:#68747D;">()</span><span style="color:#68747D;"> {</span></span>
<span class="line"><span style="color:#101820;">      fmt</span><span style="color:#68747D;">.</span><span style="color:#0077B3;">Print</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;1&quot;</span><span style="color:#68747D;">)</span></span>
<span class="line"><span style="color:#68747D;">    }).</span><span style="color:#0077B3;">DailyAt</span><span style="color:#68747D;">(</span><span style="color:#68747D;">&quot;18:00&quot;</span><span style="color:#68747D;">),</span></span>
<span class="line"><span style="color:#68747D;">  }</span></span>
<span class="line"><span style="color:#68747D;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div>`,88)]))}const u=a(r,[["render",o]]);export{m as __pageData,u as default};
